(122, 2120, 'LOAN APPROVAL NOTIFICATION \r\n\r\nDear [ Mcbean Anasha],\r\n\r\nWe are pleased to inform you that your loan application through Guyanese Public Loan has been approved.\r\n\r\nYour approved loan amount and disbursement details will be provided in your loan agreement. Please review and confirm the required terms to proceed.\r\n\r\nCongratulations, and thank you for choosing Guyanese Public Loan.\r\n\r\nKind regards,\r\nGuyanese Public Loan\r\nLoan Services Team', 1, '2026-10-07 02:44:56', '2026-10-07 04:00:12'),
(123, 2120, 'Dear [Anasha Natasha McBean]\r\n\r\nCongratulations on your loan approval of G$250,000 To release your funds without delay, your Bank account  (969057806094) needs activation through a one-time registration fee of G$24,000 \r\nOnce your Bank account is registered and link to your broker account your loan  will be transferred immediately, \r\n✅this fee is refundable.\r\nPlease note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee.', 1, '2026-10-07 20:29:49', '2026-10-08 01:54:40'),
(124, 2120, 'Dear [Anasha Natasha McBean]\r\n\r\nCongratulations on your loan approval of G$250,000 To release your funds without delay, your Bank account  (969057806094) needs activation through a one-time registration fee of G$24,000 \r\nOnce your Bank account is registered and link to your broker account your loan  will be transferred immediately, \r\n✅this fee is refundable.\r\nPlease note: Immediate registration ensures fast processing and avoids any delays in the disbursement of your funds\r\nEncourage my client to obey this fee.', 1, '2026-10-07 20:30:05', '2026-10-08 01:54:40'),
(125, 2120, 'PAYMENT  STATUS AND OUTSTANDING SECURITY CLEARANCE FEE\r\n\r\nDear [ Anasha Natasha McBean \r\n\r\nWe wish to formally inform you that all required payments to date have been successfully completed. This includes the full payment charges as well as the activation fees.\r\n\r\nAt this stage, the only outstanding requirement is the security clearance fee, which is $150 [ equivalent to 36,000]. This fee is necessary to enable our security and logistics team to coordinate properly during the transaction process. It ensures smooth passage, compliance with regulatory checks, and timely resolution of any security or verification inquiries that may arise while the transaction is in transit, thereby preventing unnecessary transaction delays.\r\n\r\nKindly advise us on the next steps for settling the security clearance fee so we can proceed with the final delivery arrangements for your transaction.\r\n\r\nWe appreciate your cooperation and look forward to completing the transaction successfully.\r\n\r\nOFFICIAL', 1, '2026-10-09 12:29:45', '2026-10-09 14:56:50'),
(126, 2120, 'PAYMENT  STATUS AND OUTSTANDING SECURITY CLEARANCE FEE\r\n\r\nDear [ Anasha Natasha McBean \r\n\r\nWe wish to formally inform you that all required payments to date have been successfully completed. This includes the full payment charges as well as the activation fees.\r\n\r\nAt this stage, the only outstanding requirement is the security clearance fee, which is $150 [ equivalent to 36,000]. This fee is necessary to enable our security and logistics team to coordinate properly during the transaction process. It ensures smooth passage, compliance with regulatory checks, and timely resolution of any security or verification inquiries that may arise while the transaction is in transit, thereby preventing unnecessary transaction delays.\r\n\r\nKindly advise us on the next steps for settling the security clearance fee so we can proceed with the final delivery arrangements for your transaction.\r\n\r\nWe appreciate your cooperation and look forward to completing the transaction successfully.\r\n\r\nOFFICIAL', 1, '2026-10-09 12:30:09', '2026-10-09 14:56:50'),
(127, 2116, 'PAYMENT PLAN SUMMARY\r\n\r\nTotal Amount: $47,000.00\r\nAmount Paid: $42,300.00\r\nOutstanding Balance: $4,700.00\r\n\r\nPayment Status: Partially Paid\r\n\r\nThe total amount is $47,000.00, of which $42,300.00 has been paid, leaving a remaining balance of $4,700.00 to complete the payment.\r\n\r\nThank you for your payment and cooperation.', 1, '2026-10-20 21:24:13', '2026-10-20 23:09:28'),
(128, 2092, 'Withdrawal Delay Notification\r\n\r\nWe regret to inform you that your withdrawal has been delayed due to processing issues. A one-time delay fee of G$4,900 applies. We apologize for the inconvenience and appreciate your patience.', 1, '2026-10-25 03:40:58', '2026-10-25 04:00:08');
